  else if(y_count>=48 && y_count<64)begin text_line=1;font_y=y_count-48;has_text=1;end
  else if(y_count>=68 && y_count<84)begin text_line=2;font_y=y_count-68;has_text=1;end
  else if(y_count>=88 && y_count<104)begin text_line=3;font_y=y_count-88;has_text=1;end
  else if(y_count>=112 && y_count<128)begin text_line=4;font_y=y_count-112;has_text=1;end
  else if(y_count>=132 && y_count<148)begin text_line=5;font_y=y_count-132;has_text=1;end
 end
end
// Glyph IDs are documented in material/picture_settings_20261022/font_manifest.json.
reg[4:0] glyph;
always @* begin
 glyph=0;
 case({text_line,column})
  7'd0:glyph=18;7'd1:glyph=19;7'd2:glyph=20;7'd3:glyph=21;
  7'd16:glyph=selected==0?14:0;7'd17:glyph=22;7'd18:glyph=23;
  7'd20:glyph=brightness[7]?12:11;7'd21:glyph=5'd1+{1'b0,b_tens};7'd22:glyph=5'd1+b_ones[3:0];
  7'd32:glyph=selected==1?14:0;7'd33:glyph=24;7'd34:glyph=25;7'd35:glyph=23;
  7'd36:glyph=contrast_level>=2?2:0;
  7'd37:glyph=5'd1+{1'b0,c_tens};7'd38:glyph=5'd1+{1'b0,c_ones};7'd39:glyph=13;
  7'd48:glyph=selected==2?14:0;
  7'd52:glyph=volume_level>=10?2:0;
  7'd53:glyph=volume_level==0?0:5'd1+{1'b0,volume_tens};7'd54:glyph=1;7'd55:glyph=13;
  7'd64:glyph=26;7'd65:glyph=27;7'd66:glyph=15;7'd67:glyph=16;
  7'd68:glyph=17;7'd69:glyph=4;7'd70:glyph=28;7'd71:glyph=29;
  7'd80:glyph=15;7'd81:glyph=16;7'd82:glyph=17;7'd83:glyph=3;
  7'd84:glyph=11;7'd85:glyph=5;7'd86:glyph=30;7'd87:glyph=31;
  default:glyph=0;
 endcase
end
// The existing font is initialized into one spare32K block, preserving9K RAM.
wire[15:0] font_word;
`ifdef __ICARUS__
// Same synchronous read contract as the protected vendor model. The native
// vendor-model test separately checks every initialized address and latency.
reg[15:0] font_sim_word;
assign font_word=font_sim_word;
always @(posedge clk)font_sim_word<=ui_font_row({glyph,font_y});
`else
function [255:0] font_init_block;
 input integer block_index;
 integer row;
 begin
  for(row=0;row<16;row=row+1)
   font_init_block[row*16+:16]=ui_font_row(block_index*16+row);
 end
endfunction
EG_PHY_BRAM32K #(
 .MODE("SP16K"),.DATA_WIDTH_A("16"),.DATA_WIDTH_B("16"),
 .REGMODE_A("NOREG"),.REGMODE_B("NOREG"),
 .WRITEMODE_A("NORMAL"),.WRITEMODE_B("NORMAL"),.SRMODE("SYNC"),
 .CSAMUX("SIG"),.CSBMUX("SIG"),.OCEAMUX("SIG"),.OCEBMUX("SIG"),
 .RSTAMUX("SIG"),.RSTBMUX("SIG"),.CLKAMUX("SIG"),.CLKBMUX("SIG"),
 .WEAMUX("SIG"),.WEBMUX("SIG"),.READBACK("OFF"),.INIT_FILE(""),
 .INIT_00(font_init_block(0)),
 .INIT_01(font_init_block(1)),
 .INIT_02(font_init_block(2)),
 .INIT_03(font_init_block(3)),
 .INIT_04(font_init_block(4)),
 .INIT_05(font_init_block(5)),
 .INIT_06(font_init_block(6)),
 .INIT_07(font_init_block(7)),
 .INIT_08(font_init_block(8)),
 .INIT_09(font_init_block(9)),
 .INIT_0A(font_init_block(10)),
 .INIT_0B(font_init_block(11)),
 .INIT_0C(font_init_block(12)),
 .INIT_0D(font_init_block(13)),
 .INIT_0E(font_init_block(14)),
 .INIT_0F(font_init_block(15)),
 .INIT_10(font_init_block(16)),
 .INIT_11(font_init_block(17)),
 .INIT_12(font_init_block(18)),
 .INIT_13(font_init_block(19)),
 .INIT_14(font_init_block(20)),
 .INIT_15(font_init_block(21)),
 .INIT_16(font_init_block(22)),
 .INIT_17(font_init_block(23)),
 .INIT_18(font_init_block(24)),
 .INIT_19(font_init_block(25)),
 .INIT_1A(font_init_block(26)),
 .INIT_1B(font_init_block(27)),
 .INIT_1C(font_init_block(28)),
 .INIT_1D(font_init_block(29)),
 .INIT_1E(font_init_block(30)),
 .INIT_1F(font_init_block(31))
) font_rom (
 .doa(font_word),.dob(),.dia(16'b0),.dib(16'b0),
 .addra({2'b0,glyph,font_y}),.addrb(11'b0),
 .bytea(1'b0),.bytewea(1'b0),.byteb(1'b0),.byteweb(1'b0),
 .csa(1'b1),.wea(1'b0),.csb(1'b0),.web(1'b0),
 .clka(clk),.rsta(1'b0),.ocea(1'b1),.clkb(clk),.rstb(1'b0),.oceb(1'b0)
);
`endif

// Box, tapered cone and two wave strokes use comparators, not extra glyphs.
wire speaker_box=pixel_x>=50 && pixel_x<=55 && y_count>=94 && y_count<=98;
wire speaker_cone=pixel_x>=55 && pixel_x<=61 &&
                 y_count>=10'd151-pixel_x && y_count<=10'd41+pixel_x;
wire speaker_wave1=(pixel_x>=65 && pixel_x<=67 &&
                   (y_count==pixel_x+10'd27 || y_count==10'd165-pixel_x)) ||
                  (pixel_x==67 && y_count>=94 && y_count<=98);
wire speaker_wave2=(pixel_x>=69 && pixel_x<=73 &&
                   (y_count==pixel_x+10'd21 || y_count==10'd171-pixel_x)) ||
                  (pixel_x==73 && y_count>=94 && y_count<=98);
wire speaker_ink=has_text && text_line==3 &&
                 (speaker_box || speaker_cone || speaker_wave1 || speaker_wave2);
wire highlighted=text_line==0 || (text_line==1 && selected==0) ||
                 (text_line==2 && selected==1) || (text_line==3 && selected==2);
wire panel=active && de && pixel_x>=16 && pixel_x<=255 && y_count>=16 && y_count<=155;
wire border=pixel_x==16 || pixel_x==255 || y_count==16 || y_count==155;
wire[7:0] dim_r={2'b0,rgb[23:18]};
wire[7:0] dim_g={2'b0,rgb[15:10]};
wire[7:0] dim_b={2'b0,rgb[7:2]};
// 64-pixel tracks. Brightness/contrast retain their original center marks;
// volume defaults to 100%, so its neutral tick is at the right end instead.
wire[6:0] brightness_position=(9'sd64+$signed({brightness[7],brightness}))>>>1;
wire[6:0] contrast_position={contrast_level,4'd0};
function[6:0] volume_track_position;
 input[3:0] level;
 begin
  case(level)
   0:volume_track_position=0;1:volume_track_position=6;2:volume_track_position=12;
   3:volume_track_position=19;4:volume_track_position=25;5:volume_track_position=32;
   6:volume_track_position=38;7:volume_track_position=44;8:volume_track_position=51;
   9:volume_track_position=57;default:volume_track_position=64;
  endcase
 end
endfunction
wire[6:0] volume_position=volume_track_position(volume_level);
wire brightness_bar=pixel_x>=176 && pixel_x<240 && y_count>=53 && y_count<=59;
wire contrast_bar=pixel_x>=176 && pixel_x<240 && y_count>=73 && y_count<=79;
wire volume_bar=pixel_x>=176 && pixel_x<240 && y_count>=93 && y_count<=99;
wire bar=brightness_bar || contrast_bar || volume_bar;
wire bar_border=pixel_x==176 || pixel_x==239 || y_count==53 || y_count==59 ||
                y_count==73 || y_count==79 || y_count==93 || y_count==99;
wire bar_center=!volume_bar && pixel_x==208;
wire volume_default_mark=pixel_x==239 && y_count>=91 && y_count<=101;
wire[6:0] bar_position=brightness_bar?brightness_position:contrast_bar?contrast_position:volume_position;
wire bar_fill=(pixel_x-10'd176)<bar_position;
wire bar_selected=(brightness_bar && selected==0)||(contrast_bar && selected==1)||
                  (volume_bar && selected==2);
// Synchronous ROM and these metadata flops sample the same input pixel.
// Select the final color from registered data only: ROM latency is the original
// output stage, so RGB/HS/VS/DE still have exactly one clock of latency.
reg[23:0] base_rgb_q;
reg[3:0] font_x_q;
reg font_eligible_q,highlighted_q;
always @(posedge clk or posedge rst)begin
 if(rst)begin
  x_count<=0;y_count<=0;de_d<=0;hs_out<=1;vs_out<=1;de_out<=0;
  base_rgb_q<=0;font_x_q<=0;font_eligible_q<=0;highlighted_q<=0;
 end else begin
  de_d<=de;
  if(!vs)begin x_count<=0;y_count<=0;end
  else if(de)x_count<=pixel_x+10'd1;
  else if(de_d)begin x_count<=0;y_count<=y_count+10'd1;end
  hs_out<=hs;vs_out<=vs;de_out<=de;
  font_x_q<=relative_x[3:0];highlighted_q<=highlighted;
  font_eligible_q<=panel && !border && !volume_default_mark && !bar && has_text;
  if(!panel)base_rgb_q<=rgb;
  else if(border)base_rgb_q<=24'h806444;
  else if(volume_default_mark)base_rgb_q<=24'h806444;
  else if(bar && (bar_border || bar_center))base_rgb_q<=24'h806444;
  else if(bar)base_rgb_q<=bar_fill?(bar_selected?24'hf5c784:24'he8ddc9):24'h423c34;
  else if(speaker_ink)base_rgb_q<=highlighted?24'hf5c784:24'he8ddc9;
  else base_rgb_q<={dim_r,dim_g,dim_b};
 end
end
always @* begin
 rgb_out=base_rgb_q;
 if(font_eligible_q && font_word[4'd15-font_x_q])
  rgb_out=highlighted_q?24'hf5c784:24'he8ddc9;
end
endmodule
